fn is_prime(n: i8) -> bool {
    // Check if n is less than 2, in which case it is not prime
    if n < 2 {
        return false;
    }

    // Iterate over possible divisors from 2 to n-1
    let mut divisor = 2;
    while divisor < n {
        // If n is divisible by the current divisor, it is not prime
        if n % divisor == 0 {
            return false;
        }
        divisor += 1; // Move to the next divisor
    }

    // If no divisors were found, n is prime
    true
}